33	function getCenterCoord(view: View, point: number[]) {
34	    // Use projected coord as center because it's linear.
35	    return (view as Geo).pointToProjected
36	        ? (view as Geo).pointToProjected(point)
37	        : view.pointToData(point);
38	}
