40	export function updateCenterAndZoom(
41	    view: View,
42	    payload: RoamPayload,
43	    zoomLimit?: {
44	        min?: number,
45	        max?: number
46	    },
47	    api?: ExtensionAPI
48	) {
49	    const previousZoom = view.getZoom();
50	    const center = view.getCenter();
51	    let zoom = payload.zoom;
52	
53	    const point = (view as Geo).projectedToPoint
54	        ? (view as Geo).projectedToPoint(center)
55	        : view.dataToPoint(center);
56	
57	    if (payload.dx != null && payload.dy != null) {
58	        point[0] -= payload.dx;
59	        point[1] -= payload.dy;
60	
61	        view.setCenter(getCenterCoord(view, point), api);
62	    }
63	    if (zoom != null) {
64	        if (zoomLimit) {
65	            const zoomMin = zoomLimit.min || 0;
66	            const zoomMax = zoomLimit.max || Infinity;
67	            zoom = Math.max(
68	                Math.min(previousZoom * zoom, zoomMax),
69	                zoomMin
70	            ) / previousZoom;
71	        }
72	
73	        // Zoom on given point(originX, originY)
74	        view.scaleX *= zoom;
75	        view.scaleY *= zoom;
76	        const fixX = (payload.originX - view.x) * (zoom - 1);
77	        const fixY = (payload.originY - view.y) * (zoom - 1);
78	
79	        view.x -= fixX;
80	        view.y -= fixY;
81	
82	        view.updateTransform();
83	        // Get the new center
84	        view.setCenter(getCenterCoord(view, point), api);
85	        view.setZoom(zoom * previousZoom);
86	    }
87	
88	    return {
89	        center: view.getCenter(),
90	        zoom: view.getZoom()
91	    };
92	}

