41	export function updateViewOnZoom(controllerHost: RoamControllerHost, zoomDelta: number, zoomX: number, zoomY: number) {
42	    const target = controllerHost.target;
43	    const zoomLimit = controllerHost.zoomLimit;
44	
45	    let newZoom = controllerHost.zoom = controllerHost.zoom || 1;
46	    newZoom *= zoomDelta;
47	    if (zoomLimit) {
48	        const zoomMin = zoomLimit.min || 0;
49	        const zoomMax = zoomLimit.max || Infinity;
50	        newZoom = Math.max(
51	            Math.min(zoomMax, newZoom),
52	            zoomMin
53	        );
54	    }
55	    const zoomScale = newZoom / controllerHost.zoom;
56	    controllerHost.zoom = newZoom;
57	    // Keep the mouse center when scaling
58	    target.x -= (zoomX - target.x) * (zoomScale - 1);
59	    target.y -= (zoomY - target.y) * (zoomScale - 1);
