import { createChart, removeChart } from '../test/ut/core/utHelper';
import { registerMap, EChartsType } from '../src/echarts.all';

function makeGeoJSON() {
    return {
        type: 'FeatureCollection',
        features: [
            {
                type: 'Feature',
                properties: { name: 'regionA' },
                geometry: {
                    type: 'Polygon',
                    coordinates: [[[0, 0], [10, 0], [10, 10], [0, 10], [0, 0]]]
                }
            }
        ]
    } as any;
}

function wheelZoom(chart: EChartsType, point: number[], wheelDelta: number) {
    // Simulate a mouse wheel zoom interaction through the zrender event bus,
    // which is what RoamController listens to ('mousewheel').
    (chart.getZr() as any).trigger('mousewheel', {
        wheelDelta: wheelDelta,
        offsetX: point[0],
        offsetY: point[1],
        event: {
            preventDefault: function () {},
            stopPropagation: function () {},
            cancelBubble: false
        }
    });
}

describe('georoam-totalzoom-event', function () {

    let chart: EChartsType;

    afterEach(function () {
        chart && removeChart(chart);
        chart = null;
    });

    it('georoam event carries totalZoom tracking cumulative zoom', function () {
        registerMap('geoRoamTotalZoomMap', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'geoRoamTotalZoomMap',
                roam: true
            }
        });

        const point = chart.convertToPixel({ geoIndex: 0 }, [5, 5]) as number[];

        const events: any[] = [];
        chart.on('georoam', function (params: any) {
            events.push(params);
        });

        // wheelDelta 120 > 3, so the zoom factor is 1.4 per interaction.
        wheelZoom(chart, point, 120);
        expect(events.length).toBe(1);
        expect(events[0].type).toBe('georoam');
        // Existing roam event fields keep working.
        expect(events[0].zoom).toBeCloseTo(1.4, 5);
        // New field: accumulated zoom ratio.
        expect(events[0].totalZoom).toBeCloseTo(1.4, 5);

        // totalZoom tracks cumulative zoom state across successive operations.
        wheelZoom(chart, point, 120);
        expect(events.length).toBe(2);
        expect(events[1].zoom).toBeCloseTo(1.4, 5);
        expect(events[1].totalZoom).toBeCloseTo(1.4 * 1.4, 5);

        // Zooming out decreases the cumulative totalZoom again.
        wheelZoom(chart, point, -120);
        expect(events.length).toBe(3);
        expect(events[2].totalZoom).toBeCloseTo(1.4, 5);
    });

    it('georoam event from pan has no totalZoom but still fires', function () {
        registerMap('geoRoamTotalZoomPanMap', makeGeoJSON());
        chart = createChart();
        chart.setOption({
            geo: {
                map: 'geoRoamTotalZoomPanMap',
                roam: true
            }
        });

        const point = chart.convertToPixel({ geoIndex: 0 }, [5, 5]) as number[];

        const events: any[] = [];
        chart.on('georoam', function (params: any) {
            events.push(params);
        });

        const zr = chart.getZr() as any;
        // Simulate a pan (drag) interaction.
        zr.trigger('mousedown', {
            offsetX: point[0],
            offsetY: point[1],
            event: {
                preventDefault: function () {},
                stopPropagation: function () {},
                cancelBubble: false
            }
        });
        zr.trigger('mousemove', {
            offsetX: point[0] + 10,
            offsetY: point[1] + 10,
            event: {
                preventDefault: function () {},
                stopPropagation: function () {},
                cancelBubble: false
            }
        });
        zr.trigger('mouseup', {
            offsetX: point[0] + 10,
            offsetY: point[1] + 10,
            event: {
                preventDefault: function () {},
                stopPropagation: function () {},
                cancelBubble: false
            }
        });

        expect(events.length).toBe(1);
        expect(events[0].dx).toBe(10);
        expect(events[0].dy).toBe(10);
    });
});

